def check(title: str, action: str, expected: str, abnormal: str, level: str = "CAB") -> dict:
    return {"title": title, "action": action, "expected": expected, "ifAbnormal": abnormal, "level": level}

def profile(prompt: str = "Подтверждены фактическое исполнение тормозного оборудования и применимый нормативный профиль?") -> dict:
    return q("profile", prompt, [("Да", "reassess"), ("Нет / не уверен", "profile-required")])

