def add_ref(s: dict, ref: dict) -> None:
    refs=s.setdefault("sourceRefs",[])
    refs[:]=[x for x in refs if x.get("sourceId") != ref["sourceId"]]
    refs.append(deepcopy(ref))

def main() -> None:
    app=load(APP_ASSET); patch=load(PATCH_ASSET)
    if app != patch: raise SystemExit("app/patch Ermak diagnostic assets differ before batch7b")
    by={s["id"]:s for s in app.get("scenarios",[])}
    for sid,route in ROUTES.items():
        if sid not in by: raise SystemExit(f"Missing {sid}")
        apply_route(by[sid], **route)
        by[sid].setdefault("actions",[{}])[0].update({"sourceBound":False,"riskClass":"normal","userFacingPolicy":"TRIAGE_ONLY_NO_REPAIR"})
        by[sid]["sourceAudit"]={"auditedAt":VERIFIED_AT,"scope":"p0_brake_safety_batch7b","status":"IMPROVE"}
        add_ref(by[sid], BRAKE_RULES_2026); add_ref(by[sid], R3508)
